"""Execute only the reviewed synthetic fixtures generated by the F22 registry."""
import json
import math
import pathlib
import py_compile
import subprocess
import sys

root = pathlib.Path('.artifacts/f22/code-fixtures').resolve()
manifest = json.loads((root / 'manifest.json').read_text(encoding='utf-8'))
results = []
for fixture in manifest['fixtures']:
    for style, filename in fixture['python'].items():
        path = (root / filename).resolve()
        assert path.parent == root and path.suffix == '.py'
        py_compile.compile(str(path), doraise=True)
        program = subprocess.run([sys.executable, str(path)], capture_output=True, text=True, check=True, timeout=60)
        result = json.loads(program.stdout.strip().splitlines()[-1])
        assert result['mode'] == 'synthetic_example_only'
        assert result['features'] == fixture['context']['features']
        assert len(result['prediction']) == 8
        assert all(math.isfinite(value) for value in result['prediction'])
        assert math.isfinite(result['value'])
        if fixture['context']['family'] == 'kmeans' and style == 'framework':
            assert 1 <= result['updates'] <= fixture['context']['epochs']
        else:
            assert result['updates'] == fixture['expected']['updates']
        if (style == 'scratch' and fixture.get('nativeParity', True)) or fixture['frameworkParity']:
            for observed, expected in zip(result['prediction'], fixture['expected']['prediction']):
                assert math.isclose(observed, expected, rel_tol=1e-7, abs_tol=1e-8), (filename, observed, expected)
            assert math.isclose(result['value'], fixture['expected']['value'], rel_tol=1e-7, abs_tol=1e-8)
        results.append({'fixture': fixture['id'], 'style': style, 'result': result})
(root / 'python-verification.json').write_text(json.dumps({'kind':'neuroforge-learning-code-execution', 'results':results}, indent=2), encoding='utf-8')
print(f'Executed {len(results)} NumPy/PyTorch fixtures; native math parity and framework contracts passed.')
